fn xmlRegStateAddTransTo(
    mut ctxt: xmlRegParserCtxtPtr,
    mut target: xmlRegStatePtr,
    mut from: c_int,
) { unsafe {
    if (*target).maxTransTo == 0 as c_int {
        (*target).maxTransTo = 8 as c_int;
        (*target).transTo = xmlMalloc.expect("non-null function pointer")(
            ((*target).maxTransTo as size_t)
                .wrapping_mul(::core::mem::size_of::<c_int>() as size_t),
        ) as *mut c_int;
        if (*target).transTo.is_null() {
            xmlRegexpErrMemory(
                ctxt,
                b"adding transition\0" as *const u8 as *const c_char,
            );
            (*target).maxTransTo = 0 as c_int;
            return;
        }
    } else if (*target).nbTransTo >= (*target).maxTransTo {
        let mut tmp: *mut c_int = ::core::ptr::null_mut::<c_int>();
        (*target).maxTransTo *= 2 as c_int;
        tmp = xmlRealloc.expect("non-null function pointer")(
            (*target).transTo as *mut c_void,
            ((*target).maxTransTo as size_t)
                .wrapping_mul(::core::mem::size_of::<c_int>() as size_t),
        ) as *mut c_int;
        if tmp.is_null() {
            xmlRegexpErrMemory(
                ctxt,
                b"adding transition\0" as *const u8 as *const c_char,
            );
            (*target).maxTransTo /= 2 as c_int;
            return;
        }
        (*target).transTo = tmp;
    }
    *(*target).transTo.offset((*target).nbTransTo as isize) = from;
    (*target).nbTransTo += 1;
} }

